.MODEL SMALL
.STACK 100H
.DATA  
B DB 5
.CODE       

MULTIPLY PROC
;BYTE MULTIPLICATION
MOV AL, 2    
MUL B    
RET    
MULTIPLY ENDP


MAIN PROC
;INITIALIZE DATA SEGMENT
MOV AX, @DATA
MOV DS, AX

    
CALL MULTIPLY
MOV BX, AX

MOV AH,4CH
INT 21H
MAIN ENDP 


END MAIN

